CREATE TABLE `velix_editorial_claims` (`id` text PRIMARY KEY NOT NULL, `run_id` text NOT NULL REFERENCES `velix_production_runs`(`id`) ON DELETE CASCADE, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `stage_id` text REFERENCES `velix_production_stages`(`id`) ON DELETE SET NULL, `chapter` integer, `segment_hash` text NOT NULL, `text` text NOT NULL, `text_hash` text NOT NULL, `kind` text NOT NULL, `kind_source` text NOT NULL DEFAULT 'agent', `confidence` real NOT NULL DEFAULT 0, `created_at` text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), `updated_at` text NOT NULL DEFAULT (datetime('now')))